{
  "positionId": "P07",
  "interviews": [
    {
      "categoryId": "P07-C2",
      "itemId": "P07-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "입사 서류를 직접 수집한 업무에서 필요한 서류와 필수 항목을 기준으로 누락 여부를 점검했는지 확인한다. 체크리스트를 만든 방법이 아니라 실제 수집한 서류의 구비 여부를 판단한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "입사자의 온보딩 서류를 수집한 상황",
          "task": "수집한 입사 서류에 누락된 서류나 필수 항목이 없는지 확인하는 일",
          "action": "입사 절차별 필요 서류와 필수 항목을 확인하고 실제 수집 자료와 대조한 내용을 설명한다.",
          "result": "수집한 입사 서류의 누락 여부를 판단한 기준과 그 적용 내용이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "입사 서류가 빠짐없이 갖춰졌다고 판단한 구체적인 기준",
          "해당 기준의 바탕이 된 입사 절차별 필요 서류와 필수 항목",
          "수집한 서류를 해당 기준과 대조해 구비 여부를 판단한 내용"
        ]
      },
      "question": "소담식품에서 입사자 온보딩 서류를 기한 안에 모으셨던데요, 입사 서류가 빠짐없이 갖춰졌는지는 무엇을 기준으로 판단하셨어요?",
      "answerTip": "직접 맡았던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "입사 서류의 구비 여부를 판단한 기준을 필요한 서류와 필수 항목 수준에서 구체적으로 설명한다.",
            "수집한 서류를 그 기준과 대조한 내용을 제시하여 누락 여부에 대한 판단이 뒷받침된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "필요 서류 목록 등 구비 여부를 판단한 기준은 제시하지만 필수 항목에 대한 설명은 제한적이다.",
            "수집한 서류를 기준과 대조했다고 설명하지만 실제로 무엇을 확인했는지는 일부만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "서류를 모았다는 설명만 있고 구비 여부를 판단한 기준이 드러나지 않는다.",
            "체크리스트를 작성한 이야기만 하거나 수집 자료를 기준과 대조한 내용을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P07-C2",
      "itemId": "P07-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "근태 기록과 구성원의 주장이 불일치하는 상황에서 근거 자료를 확인해 급여에 반영할 연장근로 시간을 판단할 수 있는지 확인한다. 급여 전체 계산이 아니라 불일치한 시간의 확정 근거에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "급여 지급 전 근태 기록의 연장근로 시간과 구성원이 주장하는 시간이 다른 상황",
          "task": "급여에 반영할 연장근로 시간을 근거에 따라 확정하는 일",
          "action": "실제 근로 사실을 확인할 자료와 그 자료에서 확인할 내용을 바탕으로 반영 시간의 판단 근거를 설명한다.",
          "result": "급여에 반영할 연장근로 시간을 확정하는 근거와 판단 논리가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "급여에 반영할 연장근로 시간을 확정할 근거",
          "출퇴근 기록이나 업무 수행 내역 등 실제 근로 사실을 확인할 자료와 확인 내용",
          "자료에서 확인한 사실이 급여 반영 시간의 판단으로 이어지는 논리"
        ]
      },
      "question": "급여 지급 전 근태 기록에 잡힌 연장근로 시간이 구성원의 주장과 다르다고 해 볼게요. 급여에 반영할 연장근로 시간은 무엇을 근거로 확정하시겠어요?",
      "answerTip": "상황을 떠올리며 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 근로 사실을 확인할 수 있는 구체적인 자료와 확인 내용을 근거로 제시한다.",
            "확인한 사실에 따라 급여 반영 시간을 판단하는 논리가 명확하며, 기록이나 주장 한쪽을 근거 없이 그대로 채택하지 않는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "급여 반영 시간의 판단 근거로 관련 자료를 제시하지만 자료에서 확인할 내용은 일부만 설명한다.",
            "근거 자료로 불일치를 판단하려는 방향은 드러나지만 반영 시간을 확정하는 논리가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "실제 근로 사실을 확인할 근거 자료나 확인 내용을 제시하지 못한다.",
            "추가 근거 없이 근태 기록이나 구성원의 주장만으로 급여 반영 시간을 정한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "거래처 데이터 분석에서 얻은 결론을 캠페인의 타깃 우선순위로 구체화할 수 있는지 확인한다. 마지막 발주 내역을 실제 연락 대상 선정 기준으로 연결한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "발주가 끊긴 거래처를 대상으로 재접촉 캠페인을 진행한 상황이다.",
          "task": "거래처별 발주 내역을 바탕으로 먼저 연락할 대상을 정해야 했다.",
          "action": "마지막 발주 품목과 시기에서 파악한 교체 수요를 연락 우선순위의 기준으로 연결한 판단을 설명한다.",
          "result": "분석에서 확인한 사실과 먼저 연락하기로 정한 거래처 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "마지막 발주 내역을 바탕으로 먼저 연락할 거래처를 고른 기준",
          "그 기준의 근거가 된 발주 품목과 시기에 대한 분석 내용",
          "분석 내용이 해당 거래처의 연락 우선순위로 이어진 이유"
        ]
      },
      "question": "오름퍼니처에서 휴면 거래처 재접촉 캠페인을 진행하셨던데요, 마지막 발주 내역을 보고 먼저 연락할 거래처를 고른 기준은 무엇이었어요?",
      "answerTip": "당시 경험 한 장면을 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "먼저 연락할 거래처를 고른 기준을 구체적으로 제시한다.",
            "발주 품목과 시기에서 파악한 내용을 근거로 설명한다.",
            "분석한 내용이 해당 거래처의 연락 우선순위로 이어진 이유를 명확하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "연락 대상 선정 기준은 제시하지만 기준을 적용한 설명이 포괄적이다.",
            "발주 내역을 참고한 사실은 확인되지만 분석 내용과 연락 우선순위 사이의 연결이 일부만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "먼저 연락할 거래처를 고른 기준을 제시하지 못한다.",
            "발주 내역의 분석 내용 없이 연락 활동만 설명하거나, 분석 내용이 연락 우선순위와 연결되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인 성과 지표를 해석해 개선 방향의 근거로 사용할 수 있는지 확인한다. 게시물 유형별 성과 지표가 광고 소재 변경 판단으로 이어진 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "꽃집 인스타그램 광고에서 게시물 유형별 클릭과 문의 DM 수를 비교한 상황이다.",
          "task": "광고 성과를 바탕으로 사용할 소재의 변경 방향을 판단해야 했다.",
          "action": "소재 변경 판단에 사용한 성과 지표를 밝히고, 게시물 유형별 차이를 어떤 의미로 해석했는지 설명한다.",
          "result": "성과 지표의 해석이 가격 표기형 소재를 선택한 근거로 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "가격 표기형 소재로 변경하는 결정에 사용한 성과 지표",
          "선택한 지표에서 확인한 게시물 유형별 성과 차이",
          "해당 성과 차이를 가격 표기형 소재의 효과와 연결한 해석"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 게시물 반응을 비교하셨던데요, 가격 표기형으로 소재를 바꾼 결정은 어떤 성과 지표를 근거로 내리셨어요?",
      "answerTip": "기억나는 내용을 차분히 풀어 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "소재 변경 결정에 사용한 성과 지표를 명확하게 제시한다.",
            "해당 지표에서 확인한 게시물 유형별 차이를 구체적으로 설명한다.",
            "성과 차이를 가격 표기형 소재의 효과로 해석한 이유가 소재 변경 결정과 일관되게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "소재 변경에 사용한 성과 지표와 대략적인 차이는 제시한다.",
            "지표의 차이가 가격 표기형 소재를 선택한 근거로 연결되지만 해석이 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "소재 변경 결정에 사용한 성과 지표를 제시하지 못한다.",
            "게시물 유형별 성과 차이를 설명하지 못하거나, 제시한 지표 해석이 소재 변경 결정과 연결되지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 확인 과정에서 발견한 이상을 근거로 투약을 중단할 수 있는지 검증한다. 진통제 처방 용량을 의심하고 투약을 멈추기로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 상황이다.",
          "task": "처방 내용을 확인하고 해당 처방대로 투약해도 되는지 판단해야 했다.",
          "action": "처방 용량과 비교 기준 사이의 차이를 확인하고, 확인되지 않은 처방으로 투약할 수 없다고 판단한 근거를 설명한다.",
          "result": "처방의 어떤 이상을 근거로 투약을 멈추었는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "해당 처방대로 투약하지 않고 멈추기로 판단한 구체적인 근거",
          "처방 용량을 의심하게 된 비교 기준과 실제 처방 내용의 차이",
          "발견한 차이가 확인 전 투약 중단이 필요하다는 판단으로 이어진 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 적이 있다고 하셨는데요, 당시 투약을 멈추기로 판단하신 근거는 무엇이었어요?",
      "answerTip": "당시 장면을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약을 멈춘 근거를 당시 처방 내용과 연결해 구체적으로 설명한다.",
            "용량을 의심한 비교 기준과 실제 처방의 차이가 명확하다.",
            "그 차이를 확인하지 않은 채 투약해서는 안 된다고 판단한 이유가 타당하게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 처방 용량을 근거로 투약을 멈추었다는 판단은 확인된다.",
            "다만 용량을 비교한 기준이나 그 차이가 투약 중단으로 이어진 이유가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추었다는 사실만 말하고 판단 근거를 설명하지 못한다.",
            "처방에서 발견한 차이나 확인 전 투약을 중단해야 한다는 판단과 무관한 답변을 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태의 변화를 간호 기록에 정확히 남기는 행동을 검증한다. 활력징후와 통증 관찰 기록에서 상태 변화를 분명하게 표현하기 위해 중시한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하고 기록한 업무 상황이다.",
          "task": "관찰한 환자 상태의 변화가 정확히 드러나도록 간호 기록을 작성해야 했다.",
          "action": "상태 변화 기록에서 중시한 점을 실제 관찰 내용과 기록 방식에 연결해 설명한다.",
          "result": "환자 상태의 변화를 기록할 때 무엇을 중요하게 판단했는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "환자 상태 변화에 관한 기록에서 가장 신경 쓴 점",
          "그 판단을 구체화하는 실제 활력징후 또는 통증 관찰 내용",
          "관찰한 변화가 기록에 정확히 드러나도록 표현한 방식과 그 이유"
